#!/usr/bin/env wolframscript
(* fit.wls *)
args = Rest[$ScriptCommandLine];
If[args === {}, Print["usage: fit.wls <file>"]; Exit[1]];
Print[Mean[Flatten[Import[First[args], "CSV"]]]];
Exit[0]

args = Rest[$ScriptCommandLine];
If[Length[args] < 1, Print["usage: tool.wls <input>"]; Exit[1]];
inputFile = First[args];
n = ToExpression[args[[2]]];
$ScriptCommandLine

scriptDir = DirectoryName[$InputFileName];
data = Import[FileNameJoin[{scriptDir, "input.csv"}]];
Print[$InputFileName]

obj = CloudObject["data/results.wl"];
CloudPut[results, obj];
CloudGet[obj]
CloudObjects[]
CloudObjectInformation[obj, "Permissions"]
DeleteObject[obj]

api = APIFunction[{"n" -> "Integer"}, Prime[#n] &, "JSON"];
url = CloudDeploy[api, "nthprime", Permissions -> "Public"];
URLExecute[url, {"n" -> 100}]
APIFunction[{"city" -> "City"}, #city["Population"] &, "JSON"]
APIFunction[{"x" -> "Number", "n" -> {"Integer", 2}}, #x^#n &]

session = StartExternalSession["Python"];
ExternalEvaluate[session, "import numpy as np"];
ExternalEvaluate[session, "np.arange(5).tolist()"]
ExternalSessions[]
DeleteObject[session]

f = ExternalFunction["Python", "lambda x: x**2 + 1"];
f[5]
f /@ Range[5]
g = ExternalFunction["Python", "def norm(v):\n    return sum(x*x for x in v) ** 0.5", "norm"];
g[{3, 4}]

task = URLSubmit["https://example.com", HandlerFunctions -> <|"BodyReceived" -> (Print[StringLength[#Body]] &)|>];
TaskWait[task]
tasks = URLSubmit /@ urls;
TaskWait[tasks]
TaskRemove[task]

f = LibraryFunctionLoad["demo_lib", "demo_I_I", {Integer}, Integer];
f[5]
g = LibraryFunctionLoad[lib, "vector_sum", {{Real, 1}}, Real];
g[RandomReal[1, 1000]]
LibraryFunctionUnload[f]
FindLibrary["demo_lib"]

Needs["DatabaseLink`"];
conn = OpenSQLConnection[JDBC["SQLite", "data.sqlite"]];
SQLExecute[conn, "SELECT name, value FROM readings WHERE value > ?", {10}]
SQLSelect[conn, "readings", {"name", "value"}]
SQLTables[conn]
CloseSQLConnection[conn]

db = RelationalDatabase["data.sqlite"];
db["Tables"]
store = EntityStore[db];
EntityRegister[store];
EntityValue["readings", "EntityCount"]
EntityClass["readings", "value" -> GreaterThan[10]] // EntityList
